def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "place_bowl": And([
            self.human_seated_at_table,
            Not(self.robot_has_tray),
            self.floor_clear,
            self.safety_zone_active
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
